#include <winsock2.h>
#include <windows.h>
#include <iphlpapi.h>
#include <stdio.h>
#include <stdlib.h>
int main(void) {
    ULONG size = 15000;
    IP_ADAPTER_ADDRESSES *buffer = malloc(size);
    if (!buffer) return 1;
    ULONG result = GetAdaptersAddresses(AF_UNSPEC,
        GAA_FLAG_SKIP_MULTICAST | GAA_FLAG_SKIP_DNS_SERVER | GAA_FLAG_SKIP_ANYCAST,
        NULL, buffer, &size);
    if (result == ERROR_BUFFER_OVERFLOW) {
        free(buffer);
        buffer = malloc(size);
        if (!buffer) return 1;
        result = GetAdaptersAddresses(AF_UNSPEC,
            GAA_FLAG_SKIP_MULTICAST | GAA_FLAG_SKIP_DNS_SERVER | GAA_FLAG_SKIP_ANYCAST,
            NULL, buffer, &size);
    }
    printf("GetAdaptersAddresses result=%lu\n", result);
    free(buffer);
    return result != NO_ERROR;
}

