import pathlib,json,shutil,sys,hashlib
P=pathlib.Path;base=P('<artifacts>');work=base/'work/local-validation';host=sys.argv[1];assert host in ('windows','linux')
rows=json.loads((work/(host+'-checks.json')).read_text());passed={r['name'] for r in rows if r['exitCode']==0}
required={'workspace-clippy','msrv-all-targets-features','final-cli-refresh','native-installation-integrity'}
required|={'native-final-gdb'} if host=='windows' else {'capi-profile',*(f'feature-{b}-{c}' for b in ('minimal','standard','full','compat') for c in ('tests','release'))}
assert required<=passed,required-passed
final=json.loads((work/(host+'-final-build.json')).read_text());binary=base/'build'/host/'release-cli'/('ariax.exe' if host=='windows' else 'ariax');assert hashlib.sha256(binary.read_bytes()).hexdigest()==final['binarySha256']
paths=[base/'build'/host/name for name in ('validation','validation-clippy','validation-msrv','validation-tmp','tmp')]
native=base/'deps'/('native-'+host)
for p in native.iterdir():
 if p.name=='install':continue
 assert p.name in {'cache','libtorrent-source','logs','openssl-inputs.json','openssl-install','openssl-source','.builder-lock'} or p.name.startswith('libtorrent-build-'),p
 paths.append(p)
record=work/(host+'-cleanup.json');removed=json.loads(record.read_text()) if record.exists() else []
for p in paths:
 assert p.is_relative_to(base) and not p.is_symlink()
 if not p.exists():continue
 files=[q for q in p.rglob('*') if q.is_file() or q.is_symlink()] if p.is_dir() else [p]
 row={'path':str(p),'files':len(files),'bytes':sum(q.lstat().st_size for q in files)}
 if p.is_dir():shutil.rmtree(p)
 else:p.unlink()
 removed.append(row);record.write_text(json.dumps(removed,indent=2)+'\n');print('Removed',row,flush=True)
assert hashlib.sha256(binary.read_bytes()).hexdigest()==final['binarySha256']
